#!/bin/bash
# Synthesize RISC-Q's PulseTableSoc for one SocSpec with Yosys (synth_xilinx, UltraScale+ family) and
# report the resources per module: LUT, FF, DSP48E2, BRAM (RAMB36/18) and URAM288.
#   bash synth.sh <spec.json> <out-dir>
# Run inside the RTL environment (rtl-env.sh). The RTL is generated by RISC-Q's own GenPulseTableSocJson
# from the same spec; Vivado is not used (it needs a licence), so the counts are Yosys's technology
# mapping of the same RTL to the same primitives, not Vivado's.
set -e
SPEC=$1
OUT=$2
mkdir -p $OUT
mill runMain riscq.soc.GenPulseTableSocJson $SPEC $OUT > $OUT/gen.log 2>&1
cd $OUT
cat > synth.ys <<'EOF'
read_verilog -sv -DSYNTHESIS PulseTableSoc.v
hierarchy -top PulseTableSoc
synth_xilinx -family xcup -top PulseTableSoc -noiopad -nobram
tee -o stat.txt stat -top PulseTableSoc
tee -q -o stat.json stat -json -top PulseTableSoc
EOF
yosys -q -l synth.log synth.ys
echo SYNTH_DONE
